<script setup lang="ts">
import{computed,nextTick,reactive,ref,watch}from'vue';import type{MColorPickerPanelProps}from'./types';import{parseHex,hsvHex}from'./color';import MValueBridge from './MValueBridge.vue';import{useReferenceConfig}from'./locale';
import{useDraftReset}from'./shared';
const props=withDefaults(defineProps<MColorPickerPanelProps>(),{alpha:false,presets:()=>['#B32620','#3D6769','#28634E','#825713','#FFFFFF','#000000']});const emit=defineEmits<{ 'update:modelValue':[value:string] }>();const{t}=useReferenceConfig();const root=ref<HTMLElement>(),state=reactive(parseHex(props.modelValue)||{h:0,s:100,v:100,a:1}),draft=ref(props.modelValue),composing=ref(false);const error=computed(()=>draft.value&&!parseHex(draft.value)?t('color.hexInvalid','请输入有效 HEX 色值。'):'');
function restore(){composing.value=false;Object.assign(state,parseHex(props.modelValue)||{h:0,s:100,v:100,a:1});draft.value=props.modelValue;root.value?.querySelectorAll<HTMLInputElement>('input[type=range]').forEach((input,index)=>{input.value=String([state.h,state.s,state.v,state.a][index]);});const hex=root.value?.querySelector<HTMLInputElement>('.ui-ri__control');if(hex)hex.value=props.modelValue;}
function publish(value:string){if(props.disabled||props.readonly)return;emit('update:modelValue',value);void nextTick(restore);}
function change(part:'h'|'s'|'v'|'a',event:Event){if(props.disabled||props.readonly)return;state[part]=Number((event.target as HTMLInputElement).value);publish(hsvHex(state,props.alpha));}
function commit(){if(!composing.value&&!error.value)publish(draft.value?hsvHex(parseHex(draft.value)!,props.alpha):'');}
watch(()=>props.modelValue,restore);
useDraftReset(root,restore);
</script>
<template><section ref="root" class="ui-ri ui-ri__panel" :aria-label="label"><span class="ui-ri__label">{{label}}</span><div class="ui-ri-color__sample" role="img" :aria-label="hsvHex(state,alpha)" :style="{backgroundColor:hsvHex(state,alpha)}"></div><label class="ui-ri__label">{{t('color.hue','色相')}} {{Math.round(state.h)}}°<input type="range" min="0" max="359" step="1" :value="state.h" :disabled="disabled||readonly" @input="change('h',$event)"></label><label class="ui-ri__label">{{t('color.saturation','饱和度')}} {{Math.round(state.s)}}%<input type="range" min="0" max="100" :value="state.s" :disabled="disabled||readonly" @input="change('s',$event)"></label><label class="ui-ri__label">{{t('color.brightness','明度')}} {{Math.round(state.v)}}%<input type="range" min="0" max="100" :value="state.v" :disabled="disabled||readonly" @input="change('v',$event)"></label><label v-if="alpha" class="ui-ri__label">{{t('color.alpha','透明度')}} {{Math.round(state.a*100)}}%<input type="range" min="0" max="1" step="0.01" :value="state.a" :disabled="disabled||readonly" @input="change('a',$event)"></label><label class="ui-ri__label">HEX<input v-model="draft" class="ui-ri__control" :disabled="disabled" :readonly="readonly" :aria-invalid="!!error||undefined" @compositionstart="composing=true" @compositionend="composing=false" @blur="commit" @keydown.enter.prevent="commit"></label><div class="ui-ri__row" :aria-label="t('color.presets','预设色板')"><button v-for="color in presets" :key="color" type="button" class="ui-ri__button ui-ri-color__preset" :aria-label="color" :style="{backgroundColor:color}" :disabled="disabled||readonly||!parseHex(color)" @click="publish(hsvHex(parseHex(color)!,alpha))"><span aria-hidden="true">{{modelValue.toUpperCase()===color.toUpperCase()?'✓':''}}</span></button></div><p v-if="error" class="ui-ri__error">{{error}}</p><MValueBridge v-bind="props" :values="modelValue?[modelValue]:[]" :error="error"/></section></template>
<style scoped>.ui-ri-color__sample{min-height:72px;border:1px solid var(--ui-color-rule);background-image:linear-gradient(45deg,#8882 25%,transparent 25%,transparent 75%,#8882 75%)}.ui-ri-color__preset{width:36px;height:36px;min-width:36px;padding:0;box-shadow:inset 0 0 0 1px #888}.ui-ri label input[type=range]{display:block;width:100%;accent-color:var(--ui-color-accent)}</style>
